import sys
def C(*ids): return ''.join(f'<sup class="r"><a href="#sb-{i}">{i}</a></sup>' for i in ids)
def sub(f,a,b):
    s=open(f).read()
    if a not in s:
        print('MISSING',f,a[:70]); return
    s=s.replace(a,b,1); open(f,'w').write(s)
# p01
